import{_ as t}from"./chunks/background-runs-panel.BtAMKGXh.js";import{_ as n,o,c as a,a2 as s}from"./chunks/framework.ecJ-2P1q.js";const r="/v0.4/assets/getting-started-01-trigger-placed.CxPywP7h.png",i="/v0.4/assets/getting-started-02-connect-drag.Dwr57Q-1.png",d="/v0.4/assets/node-search-popover.BXF3vPM8.png",h="/v0.4/assets/getting-started-03-http-connected.BLzgzAYu.png",l="/v0.4/assets/getting-started-04-http-request-config.DjY61Q6H.png",g="/v0.4/assets/getting-started-05-workflow-wired.CQhu_Sai.png",u="/v0.4/assets/getting-started-10-rename-workflow.CKOUQ7kf.png",c="/v0.4/assets/getting-started-11-workflow-named.C5OL8Qps.png",p="/v0.4/assets/getting-started-06-run-result.FghxDn2A.png",w="/v0.4/assets/getting-started-07-schedule-swapped.C_BE8Xtj.png",f="/v0.4/assets/getting-started-08-schedule-config.Cu23_t3A.png",m="/v0.4/assets/getting-started-09-run-dropdown.DC6rJHfD.png",A=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/getting-started.md","filePath":"getting-started/getting-started.md"}'),y={name:"getting-started/getting-started.md"};function b(k,e,v,T,S,_){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>By the end of this page you&#39;ll have built a small <strong><a href="./../glossary#workflow">workflow</a></strong> by hand, run it once yourself, and set it to run automatically in the background every few seconds. It assumes you&#39;ve already finished <a href="./installation">Installation</a>.</p><h2 id="open-aerini" tabindex="-1">Open Aerini <a class="header-anchor" href="#open-aerini" aria-label="Permalink to &quot;Open Aerini&quot;">​</a></h2><p>The first time you open Aerini, a welcome dialog appears with a short list of working examples, each showing how hard it is and what it needs (nothing, Ollama, an API key), and a <strong>Start with a blank canvas</strong> button. Choose <strong>Start with a blank canvas</strong>. Building one yourself, even a simple one, teaches you the parts a lot faster than reading about a finished example would.</p><p>You&#39;ll land on the main screen: a <strong><a href="./../glossary#canvas">canvas</a></strong> filling most of the window, and a sidebar on the left listing every available <strong><a href="./../glossary#node">node</a></strong>, grouped by category.</p><p>Each sidebar entry has a one-line description under its name. The <strong>Beginner</strong> button above the list keeps only the simple, common nodes, and nodes that run code on your computer carry an <strong>Advanced</strong> tag. A small <strong>Getting started</strong> checklist at the bottom left of the canvas ticks itself off as you add a trigger, add a node, connect them, fill in a field, run, and see the result; close it with the <strong>x</strong> button whenever you like, and it stays closed.</p><h2 id="step-1-add-a-trigger" tabindex="-1">Step 1: Add a trigger <a class="header-anchor" href="#step-1-add-a-trigger" aria-label="Permalink to &quot;Step 1: Add a trigger&quot;">​</a></h2><p>Every workflow starts with a <strong><a href="./../glossary#trigger">trigger</a></strong>, the node that decides when the rest of it runs. In the sidebar, under <strong>Triggers</strong>, find <strong>Manual Trigger</strong> and click it to place it on the canvas. This one starts a run only when you tell it to, which makes it the right choice while you&#39;re still building and testing.</p><p><img src="'+r+'" alt="Manual Trigger placed on the canvas, node sidebar open"></p><h2 id="step-2-add-something-for-it-to-do" tabindex="-1">Step 2: Add something for it to do <a class="header-anchor" href="#step-2-add-something-for-it-to-do" aria-label="Permalink to &quot;Step 2: Add something for it to do&quot;">​</a></h2><p>Under <strong>Core Actions</strong> in the sidebar, find <strong>HTTP Request</strong> and click it. Aerini places new nodes to the right of whatever you added last, so it should land right next to Manual Trigger with no dragging needed.</p><p>Connect the two: drag from the small dot on the right edge of Manual Trigger to the matching dot on the left edge of HTTP Request. That <strong><a href="./../glossary#connection">connection</a></strong> is what tells Aerini which node runs next.</p><p><img src="'+i+'" alt="Dragging a connection off Manual Trigger&#39;s output dot"></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If you drag a connection out and release it over empty canvas instead of an existing node, Aerini opens a small search popover so you can pick a new node and place it, already connected, in one motion. Handy once you&#39;re adding nodes faster than you&#39;re arranging them. Dragging from an empty input toward an output works the same way in reverse.</p><p><img src="'+d+'" alt="The node search popover that appears when a dragged connection is dropped on empty canvas"></p></div><p><img src="'+h+'" alt="Manual Trigger connected to HTTP Request, not yet configured"></p><p>Double-click HTTP Request to open its settings. Set <strong>URL</strong> to <code>https://httpbin.org/get</code> and leave <strong>Method</strong> as <code>GET</code>. httpbin.org is a small public service built for exactly this: it just echoes back whatever request you send it, so you get a real response without needing an account or an API key anywhere.</p><p><img src="'+l+'" alt="HTTP Request&#39;s settings panel with URL filled in"></p><h2 id="step-3-add-somewhere-to-see-the-result" tabindex="-1">Step 3: Add somewhere to see the result <a class="header-anchor" href="#step-3-add-somewhere-to-see-the-result" aria-label="Permalink to &quot;Step 3: Add somewhere to see the result&quot;">​</a></h2><p>Under <strong>Utility</strong>, find <strong>Output</strong> and click it the same way. Connect it too: right dot of HTTP Request to left dot of Output. Its job is to mark the final result of the workflow. You can leave its <strong>Label</strong> setting blank; it shows as &quot;Result&quot; by default.</p><p>You should now have three boxes in a row, wired together: Manual Trigger, HTTP Request, Output.</p><p><img src="'+g+'" alt="All three nodes wired together, before running"></p><h2 id="step-4-save-it" tabindex="-1">Step 4: Save it <a class="header-anchor" href="#step-4-save-it" aria-label="Permalink to &quot;Step 4: Save it&quot;">​</a></h2><p>Press <strong>Ctrl+S</strong> (<strong>Cmd+S</strong> on macOS). Since this workflow doesn&#39;t have a name yet, the title at the top left of the toolbar turns into an editable text box with its current text already selected.</p><p><img src="'+u+'" alt="The title field in its editable state, current text selected"></p><p>Type a name, for example <code>My First Workflow</code>, and press Enter.</p><p><img src="'+c+'" alt="The title now showing the new name"></p><h2 id="step-5-run-it" tabindex="-1">Step 5: Run it <a class="header-anchor" href="#step-5-run-it" aria-label="Permalink to &quot;Step 5: Run it&quot;">​</a></h2><p>Click <strong>Run</strong> in the top right. Aerini executes the three nodes in order, and within a second or two each one shows a short preview of its own output right on the canvas. Output&#39;s preview should show the JSON body httpbin.org sent back, including the URL it received and the headers your request carried. If a node fails instead, you&#39;ll see a small alert icon on it rather than a preview.</p><p><img src="'+p+'" alt="All three nodes after a successful run, with the Output drawer&#39;s Summary tab open"></p><p>That&#39;s one full <strong><a href="./../glossary#run">run</a></strong>, done by hand. Everything after this point is about making it happen without you.</p><h2 id="step-6-make-it-run-on-its-own" tabindex="-1">Step 6: Make it run on its own <a class="header-anchor" href="#step-6-make-it-run-on-its-own" aria-label="Permalink to &quot;Step 6: Make it run on its own&quot;">​</a></h2><p>A workflow that only runs when you click a button isn&#39;t really automated yet. To fix that, swap the trigger for one that fires on a timer.</p><p>Click Manual Trigger to select it, then press <strong>Delete</strong> (or <strong>Backspace</strong>) to remove it, which takes its connection with it. In the sidebar, under <strong>Triggers</strong> again, find <strong>Schedule</strong> and click it. Aerini adds new nodes to the right of your existing ones, so Schedule will land past Output rather than where Manual Trigger used to be; drag it over to the left of HTTP Request if you want the row to read left to right again, though where it sits on the canvas makes no difference to how it runs. Connect its right dot to HTTP Request&#39;s left dot, the same way you connected things before.</p><p><img src="'+w+'" alt="Schedule swapped in for Manual Trigger, not yet configured"></p><p>Double-click Schedule to configure it. Set <strong>Mode</strong> to <code>interval</code>, and <strong>Interval (seconds)</strong> to <code>10</code>, the shortest interval Aerini allows. Ten seconds is short on purpose here, so you can watch it fire a few times without waiting around; a real scheduled workflow would more likely run hourly, daily, or on a <a href="./../glossary#cron-expression">cron expression</a> instead.</p><p><img src="'+f+'" alt="Schedule&#39;s settings panel with Mode set to interval and Interval set to 10 seconds"></p><p>Save again with Ctrl+S (or Cmd+S).</p><h2 id="step-7-turn-on-the-schedule" tabindex="-1">Step 7: Turn on the schedule <a class="header-anchor" href="#step-7-turn-on-the-schedule" aria-label="Permalink to &quot;Step 7: Turn on the schedule&quot;">​</a></h2><p>Next to the Run button is a small arrow. Click it, and choose <strong>Schedule Run</strong> instead of the plain Run you used before.</p><p><img src="'+m+'" alt="The Run button&#39;s dropdown, showing Run Now and Schedule Run"></p><p>Aerini starts running the workflow every ten seconds in the background, whether or not this window is even open. You can watch it happen from <strong>Background Runs</strong> in the sidebar, which lists every run as it happens along with whether it succeeded.</p><h2 id="step-8-turn-it-back-off" tabindex="-1">Step 8: Turn it back off <a class="header-anchor" href="#step-8-turn-it-back-off" aria-label="Permalink to &quot;Step 8: Turn it back off&quot;">​</a></h2><p>Since it&#39;s now firing every ten seconds, stop it once you&#39;ve seen enough. Open the same Run menu and use it again to stop the workflow, or find it under <strong>Background Runs</strong> in the sidebar and stop it from there.</p><p><img src="'+t+'" alt="The Background Runs panel with a live countdown to the next scheduled fire"></p><p>Closing the window doesn&#39;t stop it: Aerini keeps running in your system tray even with no window open (on a Linux desktop with no tray it minimizes instead, since a hidden window couldn&#39;t be brought back), so the button or panel above is the actual off switch, not the window&#39;s close button.</p><h2 id="what-you-just-built" tabindex="-1">What you just built <a class="header-anchor" href="#what-you-just-built" aria-label="Permalink to &quot;What you just built&quot;">​</a></h2><p>A trigger, an action, and a place to see the result, wired together and run two different ways: once by hand, and once on a repeating schedule. That&#39;s the shape every Aerini workflow follows, no matter how many nodes it eventually grows to.</p><p>From here:</p><ul><li><a href="./concepts">Concepts</a> puts a name to everything you just did (workflow, node, connection, run) and explains how they fit together.</li><li><a href="./../guide/nodes">Nodes Reference</a> lists everything else you can build with beyond HTTP Request and Output.</li><li><a href="./../guide/keyboard-shortcuts">Keyboard Shortcuts</a> covers every shortcut, including the two you just used (<code>Ctrl+S</code>, <code>Delete</code>). The same list opens in the app itself by pressing <code>?</code> or clicking <strong>Shortcuts</strong> in the toolbar.</li><li><a href="./../guide/background-runs">Background Runs</a> covers schedules and webhook triggers in more depth, including run history.</li><li><a href="./../glossary">Glossary</a> is there for any term that comes up later and doesn&#39;t ring a bell.</li></ul>',49)])])}const P=n(y,[["render",b]]);export{A as __pageData,P as default};
